{"version":3,"file":"home-app.jsdbx","sources":["../../src/client/home-app.css","../../src/client/home-app.tsx"],"sourcesContent":["/* ─── Home Portal Landing Page ─────────────────────────────────────────────── */

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes gradientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.home-portal {
  min-height: 100vh;
  background: #0a0e1a;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 32px;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  box-sizing: border-box;
}

/* ─── Header ──────────────────────────────────────────────────────────────── */

.home-header {
  text-align: center;
  margin-bottom: 48px;
  animation: fadeInUp 0.6s ease-out;
}

.home-header__title {
  font-size: 2.4rem;
  font-weight: 700;
  color: #e2e8f0;
  margin: 0 0 8px 0;
  letter-spacing: -0.5px;
}

.home-header__subtitle {
  font-size: 1.05rem;
  color: #94a3b8;
  margin: 0 0 20px 0;
  font-weight: 400;
}

.home-header__accent {
  width: 120px;
  height: 3px;
  margin: 0 auto;
  border-radius: 2px;
  background: linear-gradient(90deg, #8b5cf6, #00c896, #3b82f6, #f59e0b);
  background-size: 300% 100%;
  animation: gradientShift 4s ease infinite;
}

/* ─── Cards Grid ──────────────────────────────────────────────────────────── */

.home-cards {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 920px;
  width: 100%;
  margin-bottom: 48px;
}

.home-card {
  background: #131a2e;
  border-radius: 14px;
  padding: 32px 28px;
  cursor: pointer;
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;
  position: relative;
  overflow: hidden;
  opacity: 0;
  animation: fadeInUp 0.5s ease-out forwards;
  display: flex;
  flex-direction: column;
}

.home-card:nth-child(1) { animation-delay: 0.1s; }
.home-card:nth-child(2) { animation-delay: 0.2s; }
.home-card:nth-child(3) { animation-delay: 0.3s; }
.home-card:nth-child(4) { animation-delay: 0.4s; }

.home-card:hover {
  transform: scale(1.02);
}

/* Card accent variants */
.home-card--purple {
  border: 1px solid rgba(139, 92, 246, 0.3);
  box-shadow: 0 0 20px rgba(139, 92, 246, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}
.home-card--purple:hover {
  border-color: rgba(139, 92, 246, 0.6);
  box-shadow: 0 0 32px rgba(139, 92, 246, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.home-card--teal {
  border: 1px solid rgba(0, 200, 150, 0.3);
  box-shadow: 0 0 20px rgba(0, 200, 150, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}
.home-card--teal:hover {
  border-color: rgba(0, 200, 150, 0.6);
  box-shadow: 0 0 32px rgba(0, 200, 150, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.home-card--blue {
  border: 1px solid rgba(59, 130, 246, 0.3);
  box-shadow: 0 0 20px rgba(59, 130, 246, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}
.home-card--blue:hover {
  border-color: rgba(59, 130, 246, 0.6);
  box-shadow: 0 0 32px rgba(59, 130, 246, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.home-card--orange {
  border: 1px solid rgba(245, 158, 11, 0.3);
  box-shadow: 0 0 20px rgba(245, 158, 11, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.03);
}
.home-card--orange:hover {
  border-color: rgba(245, 158, 11, 0.6);
  box-shadow: 0 0 32px rgba(245, 158, 11, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* Card content */
.home-card__icon {
  font-size: 2rem;
  margin-bottom: 12px;
}

.home-card__title {
  font-size: 1.15rem;
  font-weight: 600;
  color: #e2e8f0;
  margin: 0 0 4px 0;
}

.home-card__subtitle {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin: 0 0 12px 0;
}

.home-card__subtitle--purple { color: #a78bfa; }
.home-card__subtitle--teal { color: #34d399; }
.home-card__subtitle--blue { color: #60a5fa; }
.home-card__subtitle--orange { color: #fbbf24; }

.home-card__description {
  font-size: 0.88rem;
  color: #94a3b8;
  line-height: 1.5;
  margin: 0;
  flex: 1;
}

.home-card__arrow {
  position: absolute;
  top: 28px;
  right: 28px;
  font-size: 1.2rem;
  color: #475569;
  transition: color 0.2s ease, transform 0.2s ease;
}

.home-card:hover .home-card__arrow {
  color: #e2e8f0;
  transform: translateX(4px);
}

/* ─── Status Strip ────────────────────────────────────────────────────────── */

.home-status {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 32px;
  padding: 16px 32px;
  background: rgba(19, 26, 46, 0.6);
  border: 1px solid #1e2a45;
  border-radius: 10px;
  max-width: 920px;
  width: 100%;
  margin-bottom: 32px;
  opacity: 0;
  animation: fadeInUp 0.5s ease-out 0.55s forwards;
}

.home-status__item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.82rem;
  color: #94a3b8;
  white-space: nowrap;
}

.home-status__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  animation: pulse 2s ease-in-out infinite;
}

.home-status__dot--green {
  background: #22c55e;
  box-shadow: 0 0 6px rgba(34, 197, 94, 0.5);
}

.home-status__value {
  color: #e2e8f0;
  font-weight: 600;
}

/* ─── Footer ──────────────────────────────────────────────────────────────── */

.home-footer {
  text-align: center;
  color: #475569;
  font-size: 0.78rem;
  margin-top: 8px;
  opacity: 0;
  animation: fadeInUp 0.5s ease-out 0.65s forwards;
}

/* ─── Responsive ──────────────────────────────────────────────────────────── */

@media (max-width: 768px) {
  .home-cards {
    grid-template-columns: 1fr;
  }

  .home-status {
    flex-wrap: wrap;
    justify-content: center;
    gap: 16px 24px;
  }

  .home-header__title {
    font-size: 1.8rem;
  }
}
","import React, { useEffect } from 'react';
import './home-app.css';

interface WorkspaceCard {
  icon: string;
  title: string;
  subtitle: string;
  subtitleColor: string;
  description: string;
  link: string;
  accent: string;
}

const workspaces: WorkspaceCard[] = [
  {
    icon: '🏢',
    title: 'Executive Analytics Center',
    subtitle: 'CEO & Board View',
    subtitleColor: 'purple',
    description: 'Strategic KPIs, financial performance, predictive forecasts, and board-level recommendations',
    link: '/x_2145749_qc_exec_dashboard.do',
    accent: 'purple',
  },
  {
    icon: '📊',
    title: 'Operations Command Center',
    subtitle: 'Operations Leadership View',
    subtitleColor: 'teal',
    description: 'Real-time operational intelligence, PulseScore monitoring, and network health across all cities',
    link: '/x_2145749_qc_ops_dashboard.do',
    accent: 'teal',
  },
  {
    icon: '🏪',
    title: 'Dark Store Intelligence Center',
    subtitle: 'Store Manager View',
    subtitleColor: 'blue',
    description: 'Individual store health, equipment status, staff productivity, and delivery operations',
    link: '/x_2145749_qc_dark_store_dashboard.do',
    accent: 'blue',
  },
  {
    icon: '🛡️',
    title: 'Refund & Fraud Intelligence',
    subtitle: 'Risk & Compliance View',
    subtitleColor: 'orange',
    description: 'Fraud detection, refund analytics, investigation timeline, and risk mitigation',
    link: '/x_2145749_qc_fraud_dashboard.do',
    accent: 'orange',
  },
];

export default function HomeApp() {
  useEffect(() => {
    document.title = 'Quick Commerce Intelligence Platform';
  }, []);

  const handleNavigate = (link: string) => {
    window.location.href = link;
  };

  return (
    <div className="home-portal">
      {/* Header */}
      <header className="home-header">
        <h1 className="home-header__title">Quick Commerce Intelligence Platform</h1>
        <p className="home-header__subtitle">Enterprise Operations &amp; Analytics Suite</p>
        <div className="home-header__accent" />
      </header>

      {/* Workspace Cards */}
      <div className="home-cards">
        {workspaces.map((ws) => (
          <div
            key={ws.title}
            className={`home-card home-card--${ws.accent}`}
            onClick={() => handleNavigate(ws.link)}
            role="button"
            tabIndex={0}
            onKeyDown={(e) => { if (e.key === 'Enter') handleNavigate(ws.link); }}
          >
            <span className="home-card__arrow">→</span>
            <div className="home-card__icon">{ws.icon}</div>
            <h2 className="home-card__title">{ws.title}</h2>
            <p className={`home-card__subtitle home-card__subtitle--${ws.subtitleColor}`}>
              {ws.subtitle}
            </p>
            <p className="home-card__description">{ws.description}</p>
          </div>
        ))}
      </div>

      {/* Status Strip */}
      <div className="home-status">
        <div className="home-status__item">
          <span className="home-status__dot home-status__dot--green" />
          AI Engine: <span className="home-status__value">Operational</span>
        </div>
        <div className="home-status__item">
          Platform Health: <span className="home-status__value">99.9%</span>
        </div>
        <div className="home-status__item">
          Today&apos;s Revenue: <span className="home-status__value">₹8.2 Cr</span>
        </div>
        <div className="home-status__item">
          Active Users: <span className="home-status__value">3,842</span>
        </div>
        <div className="home-status__item">
          Open Alerts: <span className="home-status__value">7</span>
        </div>
      </div>

      {/* Footer */}
      <footer className="home-footer">
        Quick Commerce Enterprise Suite v2.5 • Powered by ServiceNow
      </footer>
    </div>
  );
}
